#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (ll)1e18;
const int MAXN = 6000;

vector<int> to_arr;
vector<ll> cap_arr;
vector<ll> cost_arr;
vector<int> g2[MAXN];

ll dist2[MAXN];
int pre1[MAXN], pre2[MAXN];
bool inq2[MAXN];
int n2, s2, t2;

void init2(int n, int s, int t) {
    to_arr.clear();
    cap_arr.clear();
    cost_arr.clear();
    for (int i = 0; i <= n; ++i) g2[i].clear();
    n2 = n;
    s2 = s;
    t2 = t;
}

void add_flow_edge(int u, int v, ll c, ll w) {
    int id = (int)to_arr.size();
    to_arr.push_back(v);
    cap_arr.push_back(c);
    cost_arr.push_back(w);
    to_arr.push_back(u);
    cap_arr.push_back(0);
    cost_arr.push_back(-w);
    g2[u].push_back(id);
    g2[v].push_back(id ^ 1);
}

ll get_min_cost_flow(ll f) {
    ll ans = 0;
    while (f > 0) {
        fill(dist2, dist2 + n2, INF);
        dist2[s2] = 0;
        queue<int> q;
        q.push(s2);
        inq2[s2] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq2[u] = false;
            for (int eid : g2[u]) {
                if (cap_arr[eid] > 0 && dist2[u] + cost_arr[eid] < dist2[to_arr[eid]]) {
                    dist2[to_arr[eid]] = dist2[u] + cost_arr[eid];
                    pre1[to_arr[eid]] = u;
                    pre2[to_arr[eid]] = eid;
                    if (!inq2[to_arr[eid]]) {
                        inq2[to_arr[eid]] = true;
                        q.push(to_arr[eid]);
                    }
                }
            }
        }
        if (dist2[t2] == INF) return -1;
        ll add = f;
        for (int v = t2; v != s2; v = pre1[v])
            add = min(add, cap_arr[pre2[v]]);
        f -= add;
        ans += add * dist2[t2];
        for (int v = t2; v != s2; v = pre1[v]) {
            int eid = pre2[v];
            cap_arr[eid] -= add;
            cap_arr[eid ^ 1] += add;
        }
    }
    return ans;
}

ll N, M, K, C, D;
ll A[58];
vector<int> H[57];

int32_t main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> N >> M >> K >> C >> D;
    for (ll i = 1; i <= K; ++i) {
        int x;
        cin >> x;
        A[x]++;
    }
    for (int i = 1; i <= M; ++i) {
        int x, y;
        cin >> x >> y;
        H[x].push_back(y);
        H[y].push_back(x);
    }

    init2(5103, 0, 5101);
    for (int i = 2; i <= N; ++i) add_flow_edge(0, i, A[i], 0);
    for (int i = 0; i <= 100; ++i) {
        for (int l = 1; l <= N; ++l) {
            add_flow_edge(50 * i + l, 50 * (i + 1) + l, K, 0);
            for (int j : H[l]) {
                for (ll k = 1; k <= K; ++k) {
                    add_flow_edge(50 * i + l, 50 * (i + 1) + j, 1, D * (2 * k - 1));
                }
            }
        }
    }
    for (int i = 1; i <= 101; ++i) add_flow_edge(50 * i + 1, 5101, K, C * i);
    cout << get_min_cost_flow(K) << endl;
}
